// Common harness for the top-k cooperative primitive study (dsb_experiments/topk_swarm).
//
// One translation unit per cell is generated by run.py. It includes this header and the adapter
// headers of the variant and the control, then calls topk::run_cell<...>(argc, argv). The harness
// owns input generation, the host oracle, the latency driver (chain-length slope in clock64 cycles),
// the throughput driver (one occupancy wave times a fixed call count), the drift canary, resource
// reporting and the JSON output. See README.md in this directory for the adapter contract.
//
// Build: nvcc -std=c++17 -O3 -arch=sm_100 -I<repo>/cub -I<repo>/libcudacxx/include -I<repo>/thrust
//        -I<this dir> -Xptxas -v <cell>.cu -o <cell>
#pragma once

#include <cuda_runtime.h>

#include <cuda_bf16.h>
#include <cuda_fp16.h>

#include <algorithm>
#include <chrono>
#include <climits>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <ctime>
#include <limits>
#include <numeric>
#include <random>
#include <string>
#include <type_traits>
#include <vector>

namespace topk
{

// ------------------------------------------------------------------------------------------------
// Vocabulary
// ------------------------------------------------------------------------------------------------
enum class scope
{
  subwarp,
  warp,
  block
};
enum class requirement
{
  not_guaranteed,
  prefer_smaller_index,
  prefer_larger_index
};
enum class arrangement
{
  blocked,
  striped,
  packed_striped
};
enum class output_form
{
  indices,
  pairs
};
enum class key_type
{
  fp32,
  bf16,
  fp16,
  fp64
};
enum class regime
{
  latency,
  throughput
};

inline constexpr const char* to_string(scope s)
{
  return s == scope::subwarp ? "subwarp" : s == scope::warp ? "warp" : "block";
}
inline constexpr const char* to_string(requirement r)
{
  return r == requirement::not_guaranteed ? "not_guaranteed"
       : r == requirement::prefer_smaller_index
         ? "prefer_smaller_index"
         : "prefer_larger_index";
}
inline constexpr const char* to_string(arrangement a)
{
  return a == arrangement::blocked ? "blocked" : a == arrangement::striped ? "striped" : "packed_striped";
}
inline constexpr const char* to_string(output_form o)
{
  return o == output_form::indices ? "indices" : "pairs";
}
inline constexpr const char* to_string(key_type k)
{
  return k == key_type::fp32 ? "fp32" : k == key_type::bf16 ? "bf16" : k == key_type::fp16 ? "fp16" : "fp64";
}
inline constexpr const char* to_string(regime r)
{
  return r == regime::latency ? "latency" : "throughput";
}

__host__ __device__ inline constexpr int round_up(int x, int m)
{
  return ((x + m - 1) / m) * m;
}
__host__ __device__ inline constexpr size_t align_up(size_t x, size_t a)
{
  return (x + a - 1) / a * a;
}
__host__ __device__ inline constexpr bool is_pow2(int x)
{
  return x > 0 && (x & (x - 1)) == 0;
}

// Harness constants (binding methodology, see BRIEF.md section 4)
inline constexpr int chain_lengths[]  = {1, 2, 4, 8, 16};
inline constexpr int num_chain_points = 5;
inline constexpr int num_inputs       = 16; // distinct inputs per pattern, one per chain position
inline constexpr int default_reps     = 24; // minimum repetitions per chain length
inline constexpr int throughput_reps  = 5; // best of 5 event timings
inline constexpr const char* harness_version = "0.3";

// ------------------------------------------------------------------------------------------------
// Key traits. The device input buffer holds raw key bits; the host oracle sees widened floats.
// ------------------------------------------------------------------------------------------------
template <typename KeyT>
struct key_traits;

template <>
struct key_traits<float>
{
  using bits_t                         = uint32_t;
  static constexpr key_type type       = key_type::fp32;
  static constexpr int packed_per_word = 1;
  __host__ __device__ static float from_float(float f)
  {
    return f;
  }
  __host__ __device__ static float to_float(float f)
  {
    return f;
  }
  __host__ __device__ static bits_t to_bits(float f)
  {
    bits_t b;
    memcpy(&b, &f, sizeof(b));
    return b;
  }
  __host__ __device__ static float from_bits(bits_t b)
  {
    float f;
    memcpy(&f, &b, sizeof(f));
    return f;
  }
};

template <>
struct key_traits<double>
{
  using bits_t                         = uint64_t;
  static constexpr key_type type       = key_type::fp64;
  static constexpr int packed_per_word = 1;
  __host__ __device__ static double from_float(float f)
  {
    return static_cast<double>(f);
  }
  __host__ __device__ static float to_float(double d)
  {
    return static_cast<float>(d);
  }
  __host__ __device__ static bits_t to_bits(double f)
  {
    bits_t b;
    memcpy(&b, &f, sizeof(b));
    return b;
  }
  __host__ __device__ static double from_bits(bits_t b)
  {
    double f;
    memcpy(&f, &b, sizeof(f));
    return f;
  }
};

template <>
struct key_traits<__nv_bfloat16>
{
  using bits_t                         = uint16_t;
  static constexpr key_type type       = key_type::bf16;
  static constexpr int packed_per_word = 2;
  __host__ __device__ static __nv_bfloat16 from_float(float f)
  {
    return __float2bfloat16(f);
  }
  __host__ __device__ static float to_float(__nv_bfloat16 h)
  {
    return __bfloat162float(h);
  }
  __host__ __device__ static bits_t to_bits(__nv_bfloat16 h)
  {
    bits_t b;
    memcpy(&b, &h, sizeof(b));
    return b;
  }
  __host__ __device__ static __nv_bfloat16 from_bits(bits_t b)
  {
    __nv_bfloat16 h;
    memcpy(&h, &b, sizeof(h));
    return h;
  }
};

template <>
struct key_traits<__half>
{
  using bits_t                         = uint16_t;
  static constexpr key_type type       = key_type::fp16;
  static constexpr int packed_per_word = 2;
  __host__ __device__ static __half from_float(float f)
  {
    return __float2half(f);
  }
  __host__ __device__ static float to_float(__half h)
  {
    return __half2float(h);
  }
  __host__ __device__ static bits_t to_bits(__half h)
  {
    bits_t b;
    memcpy(&b, &h, sizeof(b));
    return b;
  }
  __host__ __device__ static __half from_bits(bits_t b)
  {
    __half h;
    memcpy(&h, &b, sizeof(h));
    return h;
  }
};

template <key_type KT>
struct key_of;
template <>
struct key_of<key_type::fp32>
{
  using type = float;
};
template <>
struct key_of<key_type::bf16>
{
  using type = __nv_bfloat16;
};
template <>
struct key_of<key_type::fp16>
{
  using type = __half;
};
template <>
struct key_of<key_type::fp64>
{
  using type = double;
};

// Native "ordered before" comparator selecting the largest keys first. Comparison approaches use
// this (or their own) on the floating type directly, as the brief prescribes.
template <typename KeyT>
struct greater_t
{
  __host__ __device__ __forceinline__ bool operator()(const KeyT& a, const KeyT& b) const
  {
    if constexpr (std::is_same_v<KeyT, __nv_bfloat16> || std::is_same_v<KeyT, __half>)
    {
#if defined(__CUDA_ARCH__)
      return __hgt(a, b);
#else
      return key_traits<KeyT>::to_float(a) > key_traits<KeyT>::to_float(b);
#endif
    }
    else
    {
      return a > b;
    }
  }
};

// ------------------------------------------------------------------------------------------------
// Device utilities
// ------------------------------------------------------------------------------------------------
__device__ __forceinline__ unsigned smid()
{
  unsigned r;
  asm volatile("mov.u32 %0, %%smid;" : "=r"(r));
  return r;
}

__device__ int g_sink_var[32];

// Consume a value in a way the compiler cannot prove dead (smid is never 0xffffffff).
template <typename T>
__device__ __forceinline__ void sink(T v)
{
  if (smid() == 0xffffffffu)
  {
    *reinterpret_cast<T*>(g_sink_var) = v;
  }
}

template <int Threads>
__device__ __forceinline__ unsigned member_mask()
{
  if constexpr (Threads >= 32)
  {
    return 0xffffffffu;
  }
  else
  {
    const unsigned base = (threadIdx.x & 31u) / Threads * Threads;
    return ((1u << Threads) - 1u) << base;
  }
}

// Barrier over the cooperating group: block, full warp, or logical sub-warp.
template <int Threads>
__device__ __forceinline__ void group_sync()
{
  if constexpr (Threads > 32)
  {
    __syncthreads();
  }
  else
  {
    __syncwarp(member_mask<Threads>());
  }
}

template <int Threads>
__device__ __forceinline__ int group_lane()
{
  if constexpr (Threads > 32)
  {
    return static_cast<int>(threadIdx.x);
  }
  else
  {
    return static_cast<int>(threadIdx.x) % Threads;
  }
}

template <int Threads>
__device__ __forceinline__ int group_in_block()
{
  if constexpr (Threads > 32)
  {
    return 0;
  }
  else
  {
    return static_cast<int>(threadIdx.x) / Threads;
  }
}

// ------------------------------------------------------------------------------------------------
// Cell configuration: everything the kernels need at compile time.
//   Info    : the adapter's info struct (id, scope, data_dependent, supported())
//   A       : the adapter instantiation A<KeyT, Threads, N, K, Req>
// ------------------------------------------------------------------------------------------------
template <class Info_, class A_, class KeyT_, int Threads_, int N_, int K_, requirement Req_>
struct cell_cfg
{
  using Info                           = Info_;
  using A                              = A_;
  using KeyT                           = KeyT_;
  using traits                         = key_traits<KeyT>;
  using bits_t                         = typename traits::bits_t;
  static constexpr int Threads         = Threads_;
  static constexpr int N               = N_;
  static constexpr int K               = K_;
  static constexpr requirement Req     = Req_;
  static constexpr scope sc            = Info::scope;
  static constexpr int IPT             = N / Threads;
  static constexpr bool is_block       = (sc == scope::block);
  static constexpr int lat_block       = is_block ? Threads : 32;
  static constexpr int thr_block       = is_block ? Threads : 256;
  static constexpr int lat_groups      = lat_block / Threads;
  static constexpr int thr_groups      = thr_block / Threads;
  static constexpr bool pairs          = (A::output == output_form::pairs);
  static constexpr bool data_dependent = Info::data_dependent;
  using TS                             = typename A::TempStorage;

  static_assert(N % Threads == 0, "N must be a multiple of the thread count");
  static_assert(A::items_per_thread == IPT, "adapter items_per_thread must equal N / Threads");

  __host__ __device__ static constexpr size_t ts_bytes(int groups)
  {
    return align_up(sizeof(TS) * static_cast<size_t>(groups), 16);
  }
  __host__ __device__ static constexpr size_t out_idx_bytes(int groups)
  {
    return align_up(size_t(2) * groups * K * sizeof(int), 16);
  }
  __host__ __device__ static constexpr size_t out_key_bytes(int groups)
  {
    return pairs ? align_up(size_t(2) * groups * K * sizeof(KeyT), 16) : 0;
  }
  __host__ __device__ static constexpr size_t dyn_bytes(int groups)
  {
    return ts_bytes(groups) + out_idx_bytes(groups) + out_key_bytes(groups);
  }
};

// Shared memory carve-up for one launch: [TempStorage x groups][out_idx[2][groups][K]][out_keys...]
template <class Cfg>
struct smem_view
{
  typename Cfg::TS* ts;
  int* out_idx;
  typename Cfg::KeyT* out_keys;

  __device__ __forceinline__ smem_view(unsigned char* dyn, int groups)
  {
    ts       = reinterpret_cast<typename Cfg::TS*>(dyn);
    out_idx  = reinterpret_cast<int*>(dyn + Cfg::ts_bytes(groups));
    out_keys = Cfg::pairs
               ? reinterpret_cast<typename Cfg::KeyT*>(dyn + Cfg::ts_bytes(groups) + Cfg::out_idx_bytes(groups))
               : nullptr;
  }
  __device__ __forceinline__ int* idx_buf(int buffer, int group, int groups) const
  {
    return out_idx + (static_cast<size_t>(buffer) * groups + group) * Cfg::K;
  }
  __device__ __forceinline__ typename Cfg::KeyT* key_buf(int buffer, int group, int groups) const
  {
    return Cfg::pairs ? out_keys + (static_cast<size_t>(buffer) * groups + group) * Cfg::K : nullptr;
  }
};

// Load one group's input (N keys as raw bits) into the adapter's declared arrangement and set the
// matching source indices.
template <class KeyT, int Threads, class A>
__device__ __forceinline__ void load_input(
  const typename key_traits<KeyT>::bits_t* __restrict__ in,
  typename A::key_storage& ks,
  int (&idx)[A::items_per_thread],
  int lane)
{
  using traits      = key_traits<KeyT>;
  constexpr int IPT = A::items_per_thread;
  constexpr int T   = Threads;
  if constexpr (A::input_arrangement == arrangement::blocked)
  {
    // A thread's IPT items are contiguous: load them with the widest aligned vector a real kernel
    // would use (16 bytes, else 8, else scalar). The input buffer is 256-byte aligned and every
    // group input starts at a multiple of 64 bytes, so the vector alignment follows from IPT.
    using bits_t                     = typename traits::bits_t;
    constexpr int bytes_per_thread   = IPT * static_cast<int>(sizeof(bits_t));
    constexpr int vec_bytes          = (bytes_per_thread % 16 == 0) ? 16 : (bytes_per_thread % 8 == 0) ? 8 : 0;
    if constexpr (vec_bytes > 0)
    {
      constexpr int per_vec = vec_bytes / static_cast<int>(sizeof(bits_t));
      constexpr int vecs    = IPT / per_vec;
      using vec_t           = std::conditional_t<vec_bytes == 16, uint4, uint2>;
      const vec_t* src      = reinterpret_cast<const vec_t*>(in + lane * IPT);
#pragma unroll
      for (int v = 0; v < vecs; ++v)
      {
        const vec_t w = src[v];
        bits_t tmp[per_vec];
        memcpy(tmp, &w, sizeof(w));
#pragma unroll
        for (int s = 0; s < per_vec; ++s)
        {
          const int i = v * per_vec + s;
          ks[i]       = traits::from_bits(tmp[s]);
          idx[i]      = lane * IPT + i;
        }
      }
    }
    else
    {
#pragma unroll
      for (int i = 0; i < IPT; ++i)
      {
        const int item = lane * IPT + i;
        ks[i]          = traits::from_bits(in[item]);
        idx[i]         = item;
      }
    }
  }
  else if constexpr (A::input_arrangement == arrangement::striped)
  {
#pragma unroll
    for (int i = 0; i < IPT; ++i)
    {
      const int item = i * T + lane;
      ks[i]          = traits::from_bits(in[item]);
      idx[i]         = item;
    }
  }
  else
  {
    // packed_striped: P keys per 32-bit word, blocked inside the word, words striped across lanes
    constexpr int P     = traits::packed_per_word;
    constexpr int words = IPT / P;
    static_assert(IPT % P == 0, "packed arrangement needs IPT divisible by keys per word");
    const uint32_t* w = reinterpret_cast<const uint32_t*>(in);
#pragma unroll
    for (int j = 0; j < words; ++j)
    {
      const int word = j * T + lane;
      ks[j]          = w[word];
#pragma unroll
      for (int s = 0; s < P; ++s)
      {
        idx[j * P + s] = word * P + s;
      }
    }
  }
}

// Perturb the first element of the register-resident input with a value that is zero at runtime
// but unknown to the compiler (data-oblivious in-place chain link).
template <class KeyT, class A>
__device__ __forceinline__ void perturb_first(typename A::key_storage& ks, int dep)
{
  if constexpr (A::input_arrangement == arrangement::packed_striped)
  {
    ks[0] ^= static_cast<uint32_t>(dep);
  }
  else
  {
    using traits = key_traits<KeyT>;
    using bits_t = typename traits::bits_t;
    ks[0]        = traits::from_bits(static_cast<bits_t>(traits::to_bits(ks[0]) ^ static_cast<bits_t>(dep)));
  }
}

// Fold all inputs into one word (used by the generate-only control so every input is consumed).
template <class KeyT, class A>
__device__ __forceinline__ uint32_t
fold_inputs(const typename A::key_storage& ks, const int (&idx)[A::items_per_thread])
{
  using traits      = key_traits<KeyT>;
  constexpr int IPT = A::items_per_thread;
  uint32_t acc0 = 0, acc1 = 0, acc2 = 0, acc3 = 0;
  if constexpr (A::input_arrangement == arrangement::packed_striped)
  {
    constexpr int words = IPT / traits::packed_per_word;
#pragma unroll
    for (int j = 0; j < words; j += 4)
    {
      acc0 ^= ks[j];
      if (j + 1 < words)
      {
        acc1 ^= ks[j + 1];
      }
      if (j + 2 < words)
      {
        acc2 ^= ks[j + 2];
      }
      if (j + 3 < words)
      {
        acc3 ^= ks[j + 3];
      }
    }
  }
  else
  {
#pragma unroll
    for (int i = 0; i < IPT; i += 4)
    {
      acc0 ^= static_cast<uint32_t>(traits::to_bits(ks[i]));
      if (i + 1 < IPT)
      {
        acc1 ^= static_cast<uint32_t>(traits::to_bits(ks[i + 1]));
      }
      if (i + 2 < IPT)
      {
        acc2 ^= static_cast<uint32_t>(traits::to_bits(ks[i + 2]));
      }
      if (i + 3 < IPT)
      {
        acc3 ^= static_cast<uint32_t>(traits::to_bits(ks[i + 3]));
      }
    }
  }
  return acc0 ^ acc1 ^ acc2 ^ acc3 ^ static_cast<uint32_t>(idx[0]);
}

// The generate-only control: same arrangement, same loads, same output traffic shape, no selection.
template <class A, class KeyT, int Threads, int N, int K>
struct noop_adapter
{
  static constexpr int items_per_thread          = A::items_per_thread;
  static constexpr arrangement input_arrangement = A::input_arrangement;
  static constexpr output_form output            = A::output;
  using key_storage                              = typename A::key_storage;
  struct TempStorage
  {
    int unused;
  };
  __device__ __forceinline__ static void
  run(key_storage& ks, int (&idx)[items_per_thread], TempStorage&, int* out_idx, KeyT* out_keys)
  {
    // Every thread stores its own fold (a benign same-address race when Threads > K), so no
    // thread's loads are dead and the compiler cannot sink them into a single lane.
    const uint32_t acc = fold_inputs<KeyT, A>(ks, idx);
    const int slot     = group_lane<Threads>() % K;
    out_idx[slot]      = static_cast<int>(acc);
    if constexpr (output == output_form::pairs)
    {
      KeyT first;
      memcpy(&first, &ks[0], sizeof(KeyT));
      out_keys[slot] = first;
    }
  }
};

// ------------------------------------------------------------------------------------------------
// Kernels
// ------------------------------------------------------------------------------------------------

// Correctness: one call per group on the given input, results copied to global.
template <class Cfg, class A>
__global__ void __launch_bounds__(Cfg::lat_block) oracle_kernel(
  const typename Cfg::bits_t* __restrict__ g_in, int* __restrict__ g_out_idx, typename Cfg::bits_t* __restrict__ g_out_keys)
{
  extern __shared__ __align__(16) unsigned char dyn_smem[];
  constexpr int groups = Cfg::lat_groups;
  constexpr int T      = Cfg::Threads;
  constexpr int K      = Cfg::K;
  smem_view<Cfg> sm(dyn_smem, groups);
  const int group = group_in_block<T>();
  const int lane  = group_lane<T>();

  typename A::key_storage ks;
  int idx[Cfg::IPT];
  load_input<typename Cfg::KeyT, Cfg::Threads, A>(g_in, ks, idx, lane);
  group_sync<T>();
  A::run(ks, idx, sm.ts[group], sm.idx_buf(0, group, groups), sm.key_buf(0, group, groups));
  group_sync<T>();
  for (int t = lane; t < K; t += T)
  {
    g_out_idx[group * K + t] = sm.idx_buf(0, group, groups)[t];
    if constexpr (Cfg::pairs)
    {
      g_out_keys[group * K + t] = Cfg::traits::to_bits(sm.key_buf(0, group, groups)[t]);
    }
  }
}

// Latency: chain of `chain` serialized calls, min over `reps` repetitions of the bracketed cycles.
//   data-dependent : call n loads input ((n + dep) & 15) where dep is the previous call's first
//                    output index masked with the runtime zero `zero_mask`
//   data-oblivious : in-place chain on the register-resident input, first key xor-perturbed with
//                    the masked previous output
// A generate-only control (noop adapter) runs the identical kernel and is subtracted on the host.
template <class Cfg, class A, bool DataDep>
__global__ void __launch_bounds__(Cfg::lat_block) lat_kernel(
  const typename Cfg::bits_t* __restrict__ g_in,
  int chain,
  int reps,
  int zero_mask,
  long long* __restrict__ g_cycles,
  int* __restrict__ g_out)
{
  extern __shared__ __align__(16) unsigned char dyn_smem[];
  constexpr int groups = Cfg::lat_groups;
  constexpr int T      = Cfg::Threads;
  constexpr int N      = Cfg::N;
  smem_view<Cfg> sm(dyn_smem, groups);
  const int group = group_in_block<T>();
  const int lane  = group_lane<T>();

  typename A::key_storage ks;
  int idx[Cfg::IPT];
  load_input<typename Cfg::KeyT, Cfg::Threads, A>(g_in, ks, idx, lane);
  group_sync<T>();
  // Warm-up call: brings code and shared state in, initializes the output buffers.
  A::run(ks, idx, sm.ts[group], sm.idx_buf(0, group, groups), sm.key_buf(0, group, groups));
  group_sync<T>();
  int dep = sm.idx_buf(0, group, groups)[0];

  long long best = LLONG_MAX;
#pragma unroll 1
  for (int rep = 0; rep < reps; ++rep)
  {
    group_sync<T>();
    const long long t0 = clock64();
    asm volatile("" ::: "memory");
#pragma unroll 1
    for (int n = 0; n < chain; ++n)
    {
      if constexpr (DataDep)
      {
        const int which = (n + (dep & zero_mask)) & (num_inputs - 1);
        load_input<typename Cfg::KeyT, Cfg::Threads, A>(g_in + static_cast<size_t>(which) * N, ks, idx, lane);
      }
      else
      {
        perturb_first<typename Cfg::KeyT, A>(ks, dep & zero_mask);
      }
      int* o                   = sm.idx_buf(n & 1, group, groups);
      typename Cfg::KeyT* ok   = sm.key_buf(n & 1, group, groups);
      A::run(ks, idx, sm.ts[group], o, ok);
      group_sync<T>();
      dep = o[0];
    }
    asm volatile("" ::"r"(dep) : "memory");
    group_sync<T>();
    const long long t1 = clock64();
    best               = (t1 - t0) < best ? (t1 - t0) : best;
  }
  if (lane == 0)
  {
    g_cycles[group] = best;
    g_out[group]    = dep;
  }
  sink(dep);
}

// Throughput: every group runs `calls` calls on rotating inputs, grid is one occupancy wave.
template <class Cfg, class A>
__global__ void __launch_bounds__(Cfg::thr_block)
  thr_kernel(const typename Cfg::bits_t* __restrict__ g_in, int calls, int zero_mask, int* __restrict__ g_out)
{
  extern __shared__ __align__(16) unsigned char dyn_smem[];
  constexpr int groups = Cfg::thr_groups;
  constexpr int T      = Cfg::Threads;
  constexpr int N      = Cfg::N;
  smem_view<Cfg> sm(dyn_smem, groups);
  const int group  = group_in_block<T>();
  const int lane   = group_lane<T>();
  const int gid    = static_cast<int>(blockIdx.x) * groups + group;
  int acc          = zero_mask;

  typename A::key_storage ks;
  int idx[Cfg::IPT];
#pragma unroll 1
  for (int c = 0; c < calls; ++c)
  {
    const int which = (gid * 5 + c) & (num_inputs - 1);
    load_input<typename Cfg::KeyT, Cfg::Threads, A>(g_in + static_cast<size_t>(which) * N, ks, idx, lane);
    int* o                 = sm.idx_buf(c & 1, group, groups);
    typename Cfg::KeyT* ok = sm.key_buf(c & 1, group, groups);
    A::run(ks, idx, sm.ts[group], o, ok);
    group_sync<T>();
    acc ^= o[0];
  }
  if (lane == 0)
  {
    g_out[gid] = acc;
  }
}

// Drift canaries: a fixed shuffle chain measured in cycles (single warp) and a fixed FMA kernel
// measured in wall time (whole GPU). Independent of every adapter.
__global__ void canary_lat_kernel(long long* out, int zero)
{
  unsigned x = threadIdx.x + static_cast<unsigned>(zero);
  __syncwarp();
  const long long t0 = clock64();
  asm volatile("" ::: "memory");
#pragma unroll 1
  for (int i = 0; i < 1024; ++i)
  {
    x = __shfl_sync(0xffffffffu, x * 1664525u + 1013904223u, (threadIdx.x + 1) & 31);
  }
  asm volatile("" ::"r"(x) : "memory");
  __syncwarp();
  const long long t1 = clock64();
  if (threadIdx.x == 0)
  {
    out[0] = t1 - t0;
  }
  sink(x);
}

__global__ void __launch_bounds__(256) canary_thr_kernel(float* out, int iters, float seed)
{
  float a = seed + threadIdx.x, b = a * 0.5f, c = a * 0.25f, d = a * 0.125f;
#pragma unroll 1
  for (int i = 0; i < iters; ++i)
  {
    a = fmaf(a, 0.9999f, 0.0001f);
    b = fmaf(b, 0.9999f, 0.0002f);
    c = fmaf(c, 0.9999f, 0.0003f);
    d = fmaf(d, 0.9999f, 0.0004f);
  }
  out[blockIdx.x * blockDim.x + threadIdx.x] = a + b + c + d;
}

