#define TOPK_CHECK(call)                                                                              \
  do                                                                                                  \
  {                                                                                                   \
    cudaError_t e_ = (call);                                                                          \
    if (e_ != cudaSuccess)                                                                            \
    {                                                                                                 \
      fprintf(stderr, "CUDA error %s (%d) at %s:%d\n", cudaGetErrorString(e_), int(e_), __FILE__, __LINE__); \
      exit(3);                                                                                        \
    }                                                                                                 \
  } while (0)

inline std::string json_str(const std::string& s)
{
  std::string o = "\"";
  for (char c : s)
  {
    switch (c)
    {
      case '"':
        o += "\\\"";
        break;
      case '\\':
        o += "\\\\";
        break;
      case '\n':
        o += "\\n";
        break;
      default:
        o += c;
    }
  }
  return o + "\"";
}

inline std::string json_num(double v)
{
  if (std::isnan(v) || std::isinf(v))
  {
    return "null";
  }
  char b[64];
  snprintf(b, sizeof b, "%.10g", v);
  return b;
}

struct json
{
  bool is_array = false;
  std::vector<std::pair<std::string, std::string>> members; // key, serialized value
  static json object()
  {
    return json{};
  }
  static json array()
  {
    json j;
    j.is_array = true;
    return j;
  }
  json& add(const std::string& k, const std::string& s)
  {
    members.emplace_back(k, json_str(s));
    return *this;
  }
  json& add(const std::string& k, const char* s)
  {
    members.emplace_back(k, json_str(s));
    return *this;
  }
  json& add(const std::string& k, double v)
  {
    members.emplace_back(k, json_num(v));
    return *this;
  }
  json& add(const std::string& k, int v)
  {
    members.emplace_back(k, std::to_string(v));
    return *this;
  }
  json& add(const std::string& k, long long v)
  {
    members.emplace_back(k, std::to_string(v));
    return *this;
  }
  json& add(const std::string& k, size_t v)
  {
    members.emplace_back(k, std::to_string(v));
    return *this;
  }
  json& add(const std::string& k, bool v)
  {
    members.emplace_back(k, v ? "true" : "false");
    return *this;
  }
  json& add(const std::string& k, const json& j)
  {
    members.emplace_back(k, j.str());
    return *this;
  }
  json& add_null(const std::string& k)
  {
    members.emplace_back(k, "null");
    return *this;
  }
  json& push(const json& j)
  {
    members.emplace_back("", j.str());
    return *this;
  }
  json& push(double v)
  {
    members.emplace_back("", json_num(v));
    return *this;
  }
  json& push(long long v)
  {
    members.emplace_back("", std::to_string(v));
    return *this;
  }
  json& push(const std::string& s)
  {
    members.emplace_back("", json_str(s));
    return *this;
  }
  std::string str() const
  {
    std::string o = is_array ? "[" : "{";
    for (size_t i = 0; i < members.size(); ++i)
    {
      if (i)
      {
        o += ",";
      }
      if (!is_array)
      {
        o += json_str(members[i].first) + ":";
      }
      o += members[i].second;
    }
    return o + (is_array ? "]" : "}");
  }
};

// ------------------------------------------------------------------------------------------------
// Host: input patterns
// ------------------------------------------------------------------------------------------------
inline std::vector<float> normal_values(int n, unsigned seed)
{
  std::mt19937_64 rng(0x9E3779B97F4A7C15ull ^ (static_cast<unsigned long long>(seed) * 0xD1B54A32D192ED03ull));
  std::normal_distribution<float> dist(0.f, 1.f);
  std::vector<float> v(n);
  for (auto& x : v)
  {
    x = dist(rng);
  }
  return v;
}

inline float quantize32(float base)
{
  const float r  = std::rint(base);
  const float fr = std::rint((base - r) * 32.0f);
  return r + fr / 32.0f;
}

// Pattern definitions (BLOCK_TOPK_LATENCY_SPEC.md section 7, segmented_topk common.cuh, and the
// special-value cases of BRIEF.md section 4). The returned values are fp32 and are rounded to the
// key type afterwards, so bf16 inputs carry the ties that rounding introduces.
inline std::vector<float> make_pattern(const std::string& p, int n, int k, unsigned seed)
{
  std::vector<float> v;
  if (p == "random")
  {
    v = normal_values(n, seed);
  }
  else if (p == "quantized_random")
  {
    v = normal_values(n, seed);
    for (auto& x : v)
    {
      x = quantize32(x);
    }
  }
  else if (p == "relu_quantized")
  {
    v = normal_values(n, seed);
    for (auto& x : v)
    {
      x = quantize32(std::max(x, 0.f));
    }
  }
  else if (p == "tie_heavy")
  {
    v.resize(n);
    for (int j = 0; j < n; ++j)
    {
      v[j] = static_cast<float>(j % 64) / 64.f;
    }
  }
  else if (p == "sorted_asc" || p == "sorted_desc")
  {
    v = normal_values(n, seed);
    std::sort(v.begin(), v.end());
    if (p == "sorted_desc")
    {
      std::reverse(v.begin(), v.end());
    }
  }
  else if (p == "pivot_tie")
  {
    // 1.0 everywhere, gt_count values of 2.0 at the tail (common.cuh), gt_count < k so the k-th
    // boundary falls inside a flood of equal 1.0 keys
    const int gt = std::max(1, std::min(k / 4, n / 8));
    v.assign(n, 1.f);
    for (int j = n - gt; j < n; ++j)
    {
      v[j] = 2.f;
    }
  }
  else if (p == "all_equal")
  {
    v.assign(n, 1.f);
  }
  else if (p == "signed_zero")
  {
    // Everything negative except 2k zeros of alternating sign at random positions: the top-k are
    // zeros of both signs, so -0.0 == +0.0 decides membership under the tie-break requirement
    v = normal_values(n, seed);
    for (auto& x : v)
    {
      x = -std::fabs(x) - 1.f;
    }
    std::mt19937_64 rng(seed * 7919u + 17u);
    std::vector<int> pos(n);
    std::iota(pos.begin(), pos.end(), 0);
    std::shuffle(pos.begin(), pos.end(), rng);
    const int zeros = std::min(2 * k, n);
    for (int j = 0; j < zeros; ++j)
    {
      v[pos[j]] = (j & 1) ? -0.0f : 0.0f;
    }
  }
  else if (p == "inf_denorm")
  {
    v = normal_values(n, seed);
    std::mt19937_64 rng(seed * 104729u + 3u);
    std::vector<int> pos(n);
    std::iota(pos.begin(), pos.end(), 0);
    std::shuffle(pos.begin(), pos.end(), rng);
    const float specials[] = {
      std::numeric_limits<float>::infinity(),
      std::numeric_limits<float>::infinity(),
      -std::numeric_limits<float>::infinity(),
      -std::numeric_limits<float>::infinity(),
      1e-39f,
      -1e-39f,
      std::numeric_limits<float>::denorm_min(),
      std::numeric_limits<float>::min() / 2.f,
      3.0e38f,
      -3.0e38f};
    const int count = std::min<int>(n, static_cast<int>(sizeof(specials) / sizeof(specials[0])));
    for (int j = 0; j < count; ++j)
    {
      v[pos[j]] = specials[j];
    }
  }
  else
  {
    fprintf(stderr, "unknown pattern %s\n", p.c_str());
    exit(2);
  }
  return v;
}

template <class KeyT>
struct host_input
{
  using traits = key_traits<KeyT>;
  using bits_t = typename traits::bits_t;
  std::vector<float> values; // widened to float, the oracle's view
  std::vector<bits_t> bits; // device representation
  std::string pattern;
  unsigned seed = 0;
};

template <class KeyT>
host_input<KeyT> make_input(const std::string& pattern, int n, int k, unsigned seed)
{
  using traits = key_traits<KeyT>;
  host_input<KeyT> in;
  in.pattern = pattern;
  in.seed    = seed;
  auto f     = make_pattern(pattern, n, k, seed);
  in.values.resize(n);
  in.bits.resize(n);
  for (int j = 0; j < n; ++j)
  {
    const KeyT key = traits::from_float(f[j]);
    in.bits[j]     = traits::to_bits(key);
    in.values[j]   = traits::to_float(key);
    if (std::isnan(in.values[j]))
    {
      fprintf(stderr, "pattern %s produced NaN at %d\n", pattern.c_str(), j);
      exit(2);
    }
  }
  return in;
}

// ------------------------------------------------------------------------------------------------
// Host: oracle
// ------------------------------------------------------------------------------------------------
struct oracle_verdict
{
  bool ok = true;
  std::string why;
};

// Checks k output indices (and optionally keys) against the host reference.
//   not_guaranteed       : indices distinct and in range, multiset of selected keys equals the
//                          multiset of the k largest keys (-0.0 == +0.0 under ==)
//   prefer_smaller_index : exact index set of the k first items in (key descending, index ascending)
//   prefer_larger_index  : same with index descending
//   pairs                : every returned key equals the input key at its index
inline oracle_verdict
check_topk(const std::vector<float>& v, int k, requirement req, const int* out_idx, const float* out_keys)
{
  oracle_verdict r;
  const int n = static_cast<int>(v.size());
  std::vector<char> seen(n, 0);
  for (int i = 0; i < k; ++i)
  {
    const int ix = out_idx[i];
    if (ix < 0 || ix >= n)
    {
      r.ok  = false;
      r.why = "index out of range at output slot " + std::to_string(i) + ": " + std::to_string(ix);
      return r;
    }
    if (seen[ix])
    {
      r.ok  = false;
      r.why = "duplicate index " + std::to_string(ix);
      return r;
    }
    seen[ix] = 1;
    if (out_keys && !(out_keys[i] == v[ix]))
    {
      r.ok  = false;
      r.why = "returned key does not equal the input key at index " + std::to_string(ix);
      return r;
    }
  }
  if (req == requirement::not_guaranteed)
  {
    std::vector<float> want(v);
    std::partial_sort(want.begin(), want.begin() + k, want.end(), [](float a, float b) {
      return a > b;
    });
    want.resize(k);
    std::vector<float> got(k);
    for (int i = 0; i < k; ++i)
    {
      got[i] = v[out_idx[i]];
    }
    std::sort(got.begin(), got.end(), [](float a, float b) {
      return a > b;
    });
    for (int i = 0; i < k; ++i)
    {
      if (!(want[i] == got[i]))
      {
        r.ok = false;
        char b[160];
        snprintf(b, sizeof b, "selected key multiset differs at rank %d: want %.9g got %.9g", i, want[i], got[i]);
        r.why = b;
        return r;
      }
    }
  }
  else
  {
    std::vector<int> order(n);
    std::iota(order.begin(), order.end(), 0);
    if (req == requirement::prefer_smaller_index)
    {
      std::stable_sort(order.begin(), order.end(), [&](int a, int b) {
        return v[a] > v[b];
      });
    }
    else
    {
      std::stable_sort(order.begin(), order.end(), [&](int a, int b) {
        if (v[a] > v[b])
        {
          return true;
        }
        if (v[b] > v[a])
        {
          return false;
        }
        return a > b;
      });
    }
    std::vector<int> want(order.begin(), order.begin() + k);
    std::vector<int> got(out_idx, out_idx + k);
    std::sort(want.begin(), want.end());
    std::sort(got.begin(), got.end());
    for (int i = 0; i < k; ++i)
    {
      if (want[i] != got[i])
      {
        r.ok  = false;
        r.why = "exact index set differs: want index " + std::to_string(want[i]) + " got " + std::to_string(got[i])
              + " (sorted position " + std::to_string(i) + ")";
        return r;
      }
    }
  }
  return r;
}

// Host self-test of the oracle: the exact reference passes, a wrong index set fails. Run once per
// cell so a silently broken oracle can never bless a number.
inline bool oracle_selftest(int n, int k)
{
  if (2 * k > n)
  {
    return true;
  }
  auto v = make_pattern("signed_zero", n, k, 1);
  std::vector<int> order(n);
  std::iota(order.begin(), order.end(), 0);
  std::stable_sort(order.begin(), order.end(), [&](int a, int b) {
    return v[a] > v[b];
  });
  std::vector<int> exact(order.begin(), order.begin() + k);
  bool ok = check_topk(v, k, requirement::prefer_smaller_index, exact.data(), nullptr).ok
         && check_topk(v, k, requirement::not_guaranteed, exact.data(), nullptr).ok;
  // any-k-zeros is valid under not_guaranteed but (for 2k zeros) not under prefer_smaller_index
  std::vector<int> other(order.begin() + k, order.begin() + 2 * k);
  ok = ok && check_topk(v, k, requirement::not_guaranteed, other.data(), nullptr).ok
     && !check_topk(v, k, requirement::prefer_smaller_index, other.data(), nullptr).ok;
  // a non-top element must fail both
  std::vector<int> wrong(exact);
  wrong[0] = order[n - 1];
  ok = ok && !check_topk(v, k, requirement::not_guaranteed, wrong.data(), nullptr).ok
     && !check_topk(v, k, requirement::prefer_smaller_index, wrong.data(), nullptr).ok;
  // a duplicate index must fail
  std::vector<int> dup(exact);
  if (k > 1)
  {
    dup[1] = dup[0];
    ok     = ok && !check_topk(v, k, requirement::not_guaranteed, dup.data(), nullptr).ok;
  }
  return ok;
}

// Tie structure of one input at rank k: how many keys equal the k-th largest key, how many are
// strictly larger (the k-th boundary is a genuine tie when ties_at_k > k - strictly_above).
struct tie_stats
{
  int ties_at_k      = 0;
  int strictly_above = 0;
};

inline tie_stats tie_stats_at_k(const std::vector<float>& v, int k)
{
  std::vector<float> s(v);
  std::nth_element(s.begin(), s.begin() + (k - 1), s.end(), [](float a, float b) {
    return a > b;
  });
  const float kth = s[k - 1];
  tie_stats t;
  for (float x : v)
  {
    if (x == kth)
    {
      ++t.ties_at_k;
    }
    else if (x > kth)
    {
      ++t.strictly_above;
    }
  }
  return t;
}

