struct device_info
{
  std::string name;
  int sms          = 0;
  int major        = 0;
  int minor        = 0;
  int runtime      = 0;
  int driver       = 0;
  int clock_khz    = 0;
  size_t smem_optin = 0;
};

inline device_info query_device()
{
  device_info d;
  cudaDeviceProp p;
  TOPK_CHECK(cudaGetDeviceProperties(&p, 0));
  d.name  = p.name;
  d.sms   = p.multiProcessorCount;
  d.major = p.major;
  d.minor = p.minor;
  int clk = 0;
  if (cudaDeviceGetAttribute(&clk, cudaDevAttrClockRate, 0) != cudaSuccess)
  {
    cudaGetLastError();
    clk = 0;
  }
  d.clock_khz  = clk;
  d.smem_optin = p.sharedMemPerBlockOptin;
  TOPK_CHECK(cudaRuntimeGetVersion(&d.runtime));
  TOPK_CHECK(cudaDriverGetVersion(&d.driver));
  return d;
}

inline std::string cuda_version_string(int v)
{
  return std::to_string(v / 1000) + "." + std::to_string((v % 1000) / 10);
}

inline std::string kernel_symbol(const void* f)
{
#if CUDART_VERSION >= 12030
  const char* name = nullptr;
  if (cudaFuncGetName(&name, f) == cudaSuccess && name)
  {
    return name;
  }
#else
  (void) f;
#endif
  return "";
}

struct resources
{
  int registers      = 0;
  size_t static_smem = 0;
  size_t dyn_smem    = 0;
  size_t local_bytes = 0;
  int occupancy      = 0; // blocks per SM at the launch block size
  std::string symbol;
};

template <class Kernel>
resources query_resources(Kernel k, int block, size_t dyn)
{
  resources r;
  cudaFuncAttributes a;
  TOPK_CHECK(cudaFuncGetAttributes(&a, reinterpret_cast<const void*>(k)));
  r.registers   = a.numRegs;
  r.static_smem = a.sharedSizeBytes;
  r.dyn_smem    = dyn;
  r.local_bytes = a.localSizeBytes;
  r.symbol      = kernel_symbol(reinterpret_cast<const void*>(k));
  int occ       = 0;
  cudaError_t e = cudaOccupancyMaxActiveBlocksPerMultiprocessor(&occ, k, block, dyn);
  if (e != cudaSuccess)
  {
    cudaGetLastError();
    occ = 0;
  }
  r.occupancy = occ;
  return r;
}

inline json resources_json(const resources& r)
{
  json j = json::object();
  j.add("registers", r.registers);
  j.add("smem_bytes", static_cast<long long>(r.static_smem + r.dyn_smem));
  j.add("static_smem_bytes", static_cast<long long>(r.static_smem));
  j.add("dynamic_smem_bytes", static_cast<long long>(r.dyn_smem));
  j.add("local_bytes", static_cast<long long>(r.local_bytes));
  j.add("spill_bytes", static_cast<long long>(r.local_bytes)); // refined by run.py from ptxas -v
  j.add("occupancy_blocks_per_sm", r.occupancy);
  j.add("kernel_symbol", r.symbol);
  return j;
}

template <class Kernel>
void enable_large_smem(Kernel k, size_t dyn)
{
  if (dyn > 48 * 1024)
  {
    TOPK_CHECK(cudaFuncSetAttribute(
      reinterpret_cast<const void*>(k), cudaFuncAttributeMaxDynamicSharedMemorySize, static_cast<int>(dyn)));
  }
}

inline void fit_line(const std::vector<double>& x, const std::vector<double>& y, double& slope, double& icpt, double& r2)
{
  const int m = static_cast<int>(x.size());
  double sx = 0, sy = 0, sxx = 0, sxy = 0, syy = 0;
  for (int i = 0; i < m; ++i)
  {
    sx += x[i];
    sy += y[i];
    sxx += x[i] * x[i];
    sxy += x[i] * y[i];
    syy += y[i] * y[i];
  }
  slope = (m * sxy - sx * sy) / (m * sxx - sx * sx);
  icpt  = (sy - slope * sx) / m;
  const double ss_tot = syy - sy * sy / m;
  double ss_res       = 0;
  for (int i = 0; i < m; ++i)
  {
    const double e = y[i] - (icpt + slope * x[i]);
    ss_res += e * e;
  }
  r2 = ss_tot > 0 ? 1.0 - ss_res / ss_tot : 1.0;
}

struct canary_values
{
  double lat_cycles_per_op = 0;
  double thr_us            = 0;
};

inline canary_values run_canary(const device_info& dev)
{
  canary_values c;
  long long* d_c;
  TOPK_CHECK(cudaMalloc(&d_c, sizeof(long long)));
  long long best = LLONG_MAX;
  for (int i = 0; i < 8; ++i)
  {
    canary_lat_kernel<<<1, 32>>>(d_c, 0);
    TOPK_CHECK(cudaDeviceSynchronize());
    long long v;
    TOPK_CHECK(cudaMemcpy(&v, d_c, sizeof v, cudaMemcpyDeviceToHost));
    best = std::min(best, v);
  }
  c.lat_cycles_per_op = static_cast<double>(best) / 1024.0;
  TOPK_CHECK(cudaFree(d_c));

  const int grid = dev.sms * 8;
  float* d_f;
  TOPK_CHECK(cudaMalloc(&d_f, static_cast<size_t>(grid) * 256 * sizeof(float)));
  cudaEvent_t e0, e1;
  TOPK_CHECK(cudaEventCreate(&e0));
  TOPK_CHECK(cudaEventCreate(&e1));
  canary_thr_kernel<<<grid, 256>>>(d_f, 1 << 16, 1.0f);
  TOPK_CHECK(cudaDeviceSynchronize());
  float best_ms = 1e30f;
  for (int i = 0; i < 5; ++i)
  {
    TOPK_CHECK(cudaEventRecord(e0));
    canary_thr_kernel<<<grid, 256>>>(d_f, 1 << 16, 1.0f);
    TOPK_CHECK(cudaEventRecord(e1));
    TOPK_CHECK(cudaDeviceSynchronize());
    float ms;
    TOPK_CHECK(cudaEventElapsedTime(&ms, e0, e1));
    best_ms = std::min(best_ms, ms);
  }
  c.thr_us = best_ms * 1000.0;
  TOPK_CHECK(cudaEventDestroy(e0));
  TOPK_CHECK(cudaEventDestroy(e1));
  TOPK_CHECK(cudaFree(d_f));
  return c;
}

inline int default_calls(int n)
{
  const int c = (1 << 21) / n;
  return std::max(32, std::min(4096, c));
}

inline std::string now_iso()
{
  char b[64];
  std::time_t t = std::time(nullptr);
  std::strftime(b, sizeof b, "%Y-%m-%dT%H:%M:%SZ", std::gmtime(&t));
  return b;
}

inline std::string today()
{
  char b[32];
  std::time_t t = std::time(nullptr);
  std::strftime(b, sizeof b, "%Y-%m-%d", std::gmtime(&t));
  return b;
}

// ------------------------------------------------------------------------------------------------
// Host: options
// ------------------------------------------------------------------------------------------------
struct options
{
  std::string out        = "";
  std::string pattern    = "random";
  bool do_latency        = true;
  bool do_throughput     = true;
  bool oracle_only       = false;
  bool battery           = true; // run the full correctness battery, not only the cell's pattern
  int seeds              = 4;
  int reps               = default_reps;
  int calls              = 0; // 0: default_calls(N)
  bool verbose           = false;
};

inline options parse_options(int argc, char** argv)
{
  options o;
  for (int i = 1; i < argc; ++i)
  {
    std::string a = argv[i];
    auto next     = [&](const char* what) -> std::string {
      if (i + 1 >= argc)
      {
        fprintf(stderr, "missing value for %s\n", what);
        exit(2);
      }
      return argv[++i];
    };
    if (a == "--out")
    {
      o.out = next("--out");
    }
    else if (a == "--pattern")
    {
      o.pattern = next("--pattern");
    }
    else if (a == "--regimes")
    {
      std::string r    = next("--regimes");
      o.do_latency     = r.find("latency") != std::string::npos;
      o.do_throughput  = r.find("throughput") != std::string::npos;
    }
    else if (a == "--oracle-only")
    {
      o.oracle_only = true;
    }
    else if (a == "--no-battery")
    {
      o.battery = false;
    }
    else if (a == "--seeds")
    {
      o.seeds = atoi(next("--seeds").c_str());
    }
    else if (a == "--reps")
    {
      o.reps = std::max(default_reps, atoi(next("--reps").c_str()));
    }
    else if (a == "--calls")
    {
      o.calls = atoi(next("--calls").c_str());
    }
    else if (a == "--verbose")
    {
      o.verbose = true;
    }
    else if (a == "--help")
    {
      printf("usage: cell [--out f.json] [--pattern p] [--regimes latency,throughput] [--oracle-only] "
             "[--no-battery] [--seeds n] [--reps n] [--calls n] [--verbose]\n");
      exit(0);
    }
    else
    {
      fprintf(stderr, "unknown option %s\n", a.c_str());
      exit(2);
    }
  }
  return o;
}

// ------------------------------------------------------------------------------------------------
// Host: per-adapter measurement of one cell
// ------------------------------------------------------------------------------------------------
struct adapter_result
{
  std::string id;
  bool supported   = true;
  bool oracle_ok   = true;
  int oracle_cases = 0;
  std::vector<std::string> oracle_failures;
  bool has_latency = false;
  double lat_value = 0; // raw slope minus noop slope
  double lat_raw = 0, lat_noop = 0, lat_icpt = 0, lat_r2 = 0, lat_noop_r2 = 0;
  std::vector<long long> lat_minima, lat_noop_minima;
  resources lat_res, lat_noop_res;
  bool has_throughput = false;
  double thr_value = 0, thr_noop = 0, thr_ms = 0;
  std::vector<double> thr_ms_all;
  int thr_grid = 0, thr_calls = 0;
  long long thr_elements = 0;
  resources thr_res, thr_noop_res;
  std::vector<int> ties_at_k, strictly_above; // per measurement input
  std::string error;
};

template <class Cfg>
struct cell_runner
{
  using A      = typename Cfg::A;
  using Info   = typename Cfg::Info;
  using KeyT   = typename Cfg::KeyT;
  using traits = typename Cfg::traits;
  using bits_t = typename Cfg::bits_t;
  using Noop   = noop_adapter<A, KeyT, Cfg::Threads, Cfg::N, Cfg::K>;
  using NoopCfg =
    cell_cfg<Info, Noop, KeyT, Cfg::Threads, Cfg::N, Cfg::K, Cfg::Req>;
  static constexpr int N = Cfg::N;
  static constexpr int K = Cfg::K;

  // ---- oracle
  static bool oracle_one(const host_input<KeyT>& in, std::string& why)
  {
    constexpr int groups = Cfg::lat_groups;
    bits_t* d_in;
    int* d_idx;
    bits_t* d_keys = nullptr;
    TOPK_CHECK(cudaMalloc(&d_in, N * sizeof(bits_t)));
    TOPK_CHECK(cudaMalloc(&d_idx, static_cast<size_t>(groups) * K * sizeof(int)));
    if constexpr (Cfg::pairs)
    {
      TOPK_CHECK(cudaMalloc(&d_keys, static_cast<size_t>(groups) * K * sizeof(bits_t)));
    }
    TOPK_CHECK(cudaMemcpy(d_in, in.bits.data(), N * sizeof(bits_t), cudaMemcpyHostToDevice));
    TOPK_CHECK(cudaMemset(d_idx, 0xff, static_cast<size_t>(groups) * K * sizeof(int)));
    const size_t dyn = Cfg::dyn_bytes(groups);
    auto kern        = oracle_kernel<Cfg, A>;
    enable_large_smem(kern, dyn);
    kern<<<1, Cfg::lat_block, dyn>>>(d_in, d_idx, d_keys);
    cudaError_t e = cudaDeviceSynchronize();
    if (e != cudaSuccess)
    {
      why = std::string("kernel failure: ") + cudaGetErrorString(e);
      cudaGetLastError();
      cudaFree(d_in);
      cudaFree(d_idx);
      if (d_keys)
      {
        cudaFree(d_keys);
      }
      return false;
    }
    std::vector<int> h_idx(static_cast<size_t>(groups) * K);
    TOPK_CHECK(cudaMemcpy(h_idx.data(), d_idx, h_idx.size() * sizeof(int), cudaMemcpyDeviceToHost));
    std::vector<float> h_keys;
    if constexpr (Cfg::pairs)
    {
      std::vector<bits_t> kb(static_cast<size_t>(groups) * K);
      TOPK_CHECK(cudaMemcpy(kb.data(), d_keys, kb.size() * sizeof(bits_t), cudaMemcpyDeviceToHost));
      h_keys.resize(kb.size());
      for (size_t i = 0; i < kb.size(); ++i)
      {
        h_keys[i] = traits::to_float(traits::from_bits(kb[i]));
      }
    }
    bool ok = true;
    for (int g = 0; g < groups && ok; ++g)
    {
      auto v = check_topk(in.values, K, Cfg::Req, h_idx.data() + static_cast<size_t>(g) * K,
                          Cfg::pairs ? h_keys.data() + static_cast<size_t>(g) * K : nullptr);
      if (!v.ok)
      {
        ok  = false;
        why = (groups > 1 ? "group " + std::to_string(g) + ": " : std::string()) + v.why;
      }
    }
    TOPK_CHECK(cudaFree(d_in));
    TOPK_CHECK(cudaFree(d_idx));
    if (d_keys)
    {
      TOPK_CHECK(cudaFree(d_keys));
    }
    return ok;
  }

  static void run_oracle(const options& o, adapter_result& r)
  {
    struct item
    {
      const char* pattern;
      int seeds;
    };
    std::vector<item> battery;
    battery.push_back({o.pattern.c_str(), o.seeds});
    if (o.battery)
    {
      const char* extra[] = {"tie_heavy", "sorted_asc", "sorted_desc", "pivot_tie", "all_equal", "signed_zero",
                             "inf_denorm", "quantized_random", "relu_quantized"};
      for (const char* p : extra)
      {
        if (o.pattern != p)
        {
          battery.push_back({p, 1});
        }
      }
      if (o.pattern != "random")
      {
        battery.push_back({"random", 2});
      }
    }
    for (const auto& it : battery)
    {
      for (int s = 0; s < it.seeds; ++s)
      {
        auto in = make_input<KeyT>(it.pattern, N, K, static_cast<unsigned>(s));
        std::string why;
        ++r.oracle_cases;
        if (!oracle_one(in, why))
        {
          r.oracle_ok = false;
          r.oracle_failures.push_back(std::string(it.pattern) + " seed " + std::to_string(s) + ": " + why);
          if (o.verbose)
          {
            fprintf(stderr, "  oracle FAIL %s %s seed %d: %s\n", r.id.c_str(), it.pattern, s, why.c_str());
          }
        }
      }
    }
  }

  // ---- latency
  template <class C, class Ad>
  static void latency_sweep(const bits_t* d_in, int reps, std::vector<long long>& minima, resources& res)
  {
    constexpr int groups = C::lat_groups;
    const size_t dyn     = C::dyn_bytes(groups);
    auto kern            = lat_kernel<C, Ad, C::data_dependent>;
    enable_large_smem(kern, dyn);
    res = query_resources(kern, C::lat_block, dyn);
    long long* d_c;
    int* d_o;
    TOPK_CHECK(cudaMalloc(&d_c, groups * sizeof(long long)));
    TOPK_CHECK(cudaMalloc(&d_o, groups * sizeof(int)));
    minima.assign(num_chain_points, LLONG_MAX);
    // Two full sweeps, the min of both per chain length, so a one-off disturbance cannot bias a point
    for (int pass = 0; pass < 2; ++pass)
    {
      for (int i = 0; i < num_chain_points; ++i)
      {
        kern<<<1, C::lat_block, dyn>>>(d_in, chain_lengths[i], reps, 0, d_c, d_o);
        TOPK_CHECK(cudaDeviceSynchronize());
        std::vector<long long> c(groups);
        TOPK_CHECK(cudaMemcpy(c.data(), d_c, groups * sizeof(long long), cudaMemcpyDeviceToHost));
        minima[i] = std::min(minima[i], c[0]);
      }
    }
    TOPK_CHECK(cudaFree(d_c));
    TOPK_CHECK(cudaFree(d_o));
  }

  static void run_latency(const options& o, const bits_t* d_in, adapter_result& r)
  {
    std::vector<double> x(chain_lengths, chain_lengths + num_chain_points), y, yn;
    latency_sweep<Cfg, A>(d_in, o.reps, r.lat_minima, r.lat_res);
    latency_sweep<NoopCfg, Noop>(d_in, o.reps, r.lat_noop_minima, r.lat_noop_res);
    for (int i = 0; i < num_chain_points; ++i)
    {
      y.push_back(static_cast<double>(r.lat_minima[i]));
      yn.push_back(static_cast<double>(r.lat_noop_minima[i]));
    }
    double s, b, r2, sn, bn, r2n;
    fit_line(x, y, s, b, r2);
    fit_line(x, yn, sn, bn, r2n);
    r.lat_raw     = s;
    r.lat_icpt    = b;
    r.lat_r2      = r2;
    r.lat_noop    = sn;
    r.lat_noop_r2 = r2n;
    r.lat_value   = s - sn;
    r.has_latency = true;
  }

  // ---- throughput
  template <class C, class Ad>
  static bool throughput_one(const bits_t* d_in, int calls, const device_info& dev, double& gelem, double& best_ms,
                             std::vector<double>& all_ms, int& grid, long long& elements, resources& res)
  {
    constexpr int groups = C::thr_groups;
    const size_t dyn     = C::dyn_bytes(groups);
    auto kern            = thr_kernel<C, Ad>;
    enable_large_smem(kern, dyn);
    res = query_resources(kern, C::thr_block, dyn);
    if (res.occupancy <= 0)
    {
      return false;
    }
    grid = res.occupancy * dev.sms;
    int* d_o;
    TOPK_CHECK(cudaMalloc(&d_o, static_cast<size_t>(grid) * groups * sizeof(int)));
    cudaEvent_t e0, e1;
    TOPK_CHECK(cudaEventCreate(&e0));
    TOPK_CHECK(cudaEventCreate(&e1));
    kern<<<grid, C::thr_block, dyn>>>(d_in, calls, 0, d_o);
    cudaError_t e = cudaDeviceSynchronize();
    if (e != cudaSuccess)
    {
      cudaGetLastError();
      cudaFree(d_o);
      return false;
    }
    best_ms = 1e30;
    all_ms.clear();
    for (int i = 0; i < throughput_reps; ++i)
    {
      TOPK_CHECK(cudaEventRecord(e0));
      kern<<<grid, C::thr_block, dyn>>>(d_in, calls, 0, d_o);
      TOPK_CHECK(cudaEventRecord(e1));
      TOPK_CHECK(cudaDeviceSynchronize());
      float ms;
      TOPK_CHECK(cudaEventElapsedTime(&ms, e0, e1));
      all_ms.push_back(ms);
      best_ms = std::min(best_ms, static_cast<double>(ms));
    }
    elements = static_cast<long long>(grid) * groups * calls * N;
    gelem    = static_cast<double>(elements) / (best_ms * 1e-3) / 1e9;
    TOPK_CHECK(cudaEventDestroy(e0));
    TOPK_CHECK(cudaEventDestroy(e1));
    TOPK_CHECK(cudaFree(d_o));
    return true;
  }

  static void run_throughput(const options& o, const bits_t* d_in, const device_info& dev, adapter_result& r)
  {
    const int calls = o.calls > 0 ? o.calls : default_calls(N);
    r.thr_calls     = calls;
    std::vector<double> dummy;
    double noop_ms;
    int noop_grid;
    long long noop_el;
    if (!throughput_one<Cfg, A>(d_in, calls, dev, r.thr_value, r.thr_ms, r.thr_ms_all, r.thr_grid, r.thr_elements,
                                r.thr_res))
    {
      r.error += "throughput kernel could not run (occupancy 0 or launch failure); ";
      return;
    }
    throughput_one<NoopCfg, Noop>(d_in, calls, dev, r.thr_noop, noop_ms, dummy, noop_grid, noop_el, r.thr_noop_res);
    r.has_throughput = true;
  }

  // ---- all of it
  static adapter_result run(const options& o, const device_info& dev)
  {
    adapter_result r;
    r.id = Info::id;
    // num_inputs distinct inputs of the cell's pattern (seeds disjoint from the oracle seeds), and
    // their tie structure at rank k (bf16 rows tie at the pivot routinely, the numbers must say so)
    std::vector<bits_t> h(static_cast<size_t>(num_inputs) * N);
    for (int i = 0; i < num_inputs; ++i)
    {
      auto in = make_input<KeyT>(o.pattern, N, K, 1000u + i);
      std::copy(in.bits.begin(), in.bits.end(), h.begin() + static_cast<size_t>(i) * N);
      const tie_stats t = tie_stats_at_k(in.values, K);
      r.ties_at_k.push_back(t.ties_at_k);
      r.strictly_above.push_back(t.strictly_above);
    }
    run_oracle(o, r);
    if (!r.oracle_ok || o.oracle_only)
    {
      return r;
    }
    bits_t* d_in;
    TOPK_CHECK(cudaMalloc(&d_in, h.size() * sizeof(bits_t)));
    TOPK_CHECK(cudaMemcpy(d_in, h.data(), h.size() * sizeof(bits_t), cudaMemcpyHostToDevice));
    if (o.do_latency)
    {
      run_latency(o, d_in, r);
    }
    if (o.do_throughput)
    {
      run_throughput(o, d_in, dev, r);
    }
    TOPK_CHECK(cudaFree(d_in));
    return r;
  }
};

inline json adapter_json(const adapter_result& r)
{
  json j = json::object();
  j.add("id", r.id);
  j.add("supported", r.supported);
  j.add("oracle_passed", r.oracle_ok);
  j.add("oracle_cases", r.oracle_cases);
  json f = json::array();
  for (auto& s : r.oracle_failures)
  {
    f.push(s);
  }
  j.add("oracle_failures", f);
  if (!r.ties_at_k.empty())
  {
    json t = json::object(), a = json::array(), b = json::array();
    int mx = 0;
    double mean = 0;
    for (size_t i = 0; i < r.ties_at_k.size(); ++i)
    {
      a.push(static_cast<long long>(r.ties_at_k[i]));
      b.push(static_cast<long long>(r.strictly_above[i]));
      mx = std::max(mx, r.ties_at_k[i]);
      mean += r.ties_at_k[i];
    }
    mean /= static_cast<double>(r.ties_at_k.size());
    t.add("ties_at_k", a);
    t.add("strictly_above_k", b);
    t.add("ties_at_k_mean", mean);
    t.add("ties_at_k_max", mx);
    j.add("input_tie_stats", t);
  }
  if (!r.error.empty())
  {
    j.add("error", r.error);
  }
  if (r.has_latency)
  {
    json l = json::object();
    l.add("cycles_per_call", r.lat_value);
    l.add("slope_raw", r.lat_raw);
    l.add("slope_noop", r.lat_noop);
    l.add("intercept_raw", r.lat_icpt);
    l.add("r2_raw", r.lat_r2);
    l.add("r2_noop", r.lat_noop_r2);
    json m = json::array(), mn = json::array();
    for (auto v : r.lat_minima)
    {
      m.push(v);
    }
    for (auto v : r.lat_noop_minima)
    {
      mn.push(v);
    }
    l.add("chain_minima", m);
    l.add("chain_minima_noop", mn);
    l.add("resources", resources_json(r.lat_res));
    l.add("resources_noop", resources_json(r.lat_noop_res));
    j.add("latency", l);
  }
  if (r.has_throughput)
  {
    json t = json::object();
    t.add("gelem_per_s", r.thr_value);
    t.add("gelem_per_s_noop", r.thr_noop);
    t.add("best_ms", r.thr_ms);
    json all = json::array();
    for (auto v : r.thr_ms_all)
    {
      all.push(v);
    }
    t.add("all_ms", all);
    t.add("grid", r.thr_grid);
    t.add("calls", r.thr_calls);
    t.add("elements", r.thr_elements);
    t.add("resources", resources_json(r.thr_res));
    t.add("resources_noop", resources_json(r.thr_noop_res));
    j.add("throughput", t);
  }
  return j;
}

// Assemble the schema-shaped cell objects (one per regime) for a variant with its control.
template <class KeyT>
json make_cells(const adapter_result& v,
                const adapter_result* c,
                const std::string& control_name,
                int threads,
                int n,
                int k,
                requirement req,
                output_form out,
                const std::string& pattern,
                const canary_values& c0,
                const canary_values& c1)
{
  json cells = json::array();
  auto base  = [&](const char* reg, const char* metric) {
    json j = json::object();
    j.add("key_type", to_string(key_traits<KeyT>::type));
    j.add("value_type", "int32");
    j.add("output_form", to_string(out));
    j.add("n", n);
    j.add("k", k);
    j.add("threads", threads);
    j.add("requirement", to_string(req));
    j.add("input_pattern", pattern);
    j.add("regime", reg);
    j.add("metric", metric);
    if (!v.ties_at_k.empty())
    {
      int mx = 0;
      double mean = 0;
      for (int t : v.ties_at_k)
      {
        mx = std::max(mx, t);
        mean += t;
      }
      j.add("ties_at_k_mean", mean / static_cast<double>(v.ties_at_k.size()));
      j.add("ties_at_k_max", mx);
    }
    return j;
  };
  if (v.has_latency)
  {
    json j = base("latency", "cycles_per_call");
    j.add("value", v.lat_value);
    if (c && c->has_latency)
    {
      j.add("control_name", control_name);
      j.add("control_value", c->lat_value);
    }
    else
    {
      j.add("control_missing", true);
    }
    j.add("canary_start", c0.lat_cycles_per_op);
    j.add("canary_end", c1.lat_cycles_per_op);
    j.add("resources", resources_json(v.lat_res));
    cells.push(j);
  }
  if (v.has_throughput)
  {
    json j = base("throughput", "gelem_per_s");
    j.add("value", v.thr_value);
    if (c && c->has_throughput)
    {
      j.add("control_name", control_name);
      j.add("control_value", c->thr_value);
    }
    else
    {
      j.add("control_missing", true);
    }
    j.add("canary_start", c0.thr_us);
    j.add("canary_end", c1.thr_us);
    j.add("resources", resources_json(v.thr_res));
    j.add("harness_ceiling_gelem_per_s", v.thr_noop);
    cells.push(j);
  }
  return cells;
}

template <class Info, class KeyT, int Threads, int N, int K, requirement Req>
json contract_json()
{
  json j = json::object();
  j.add("id", Info::id);
  j.add("scope", to_string(Info::scope));
  j.add("data_dependent", Info::data_dependent);
  j.add("threads", Threads);
  j.add("n", N);
  j.add("k", K);
  j.add("key_type", to_string(key_traits<KeyT>::type));
  j.add("requirement", to_string(Req));
  return j;
}

template <class Cfg>
json adapter_static_json()
{
  json j = json::object();
  j.add("items_per_thread", Cfg::IPT);
  j.add("input_arrangement", to_string(Cfg::A::input_arrangement));
  j.add("output_form", to_string(Cfg::A::output));
  j.add("temp_storage_bytes", static_cast<long long>(sizeof(typename Cfg::TS)));
  j.add("latency_block", Cfg::lat_block);
  j.add("throughput_block", Cfg::thr_block);
  j.add("groups_per_throughput_block", Cfg::thr_groups);
  return j;
}

// ------------------------------------------------------------------------------------------------
// The cell entry point. V and C are adapter class templates, VInfo and CInfo their info structs.
// CReq is the requirement the control is instantiated with (normally Req, run.py's --control-req
// lets a prefer_smaller_index variant run against the reference's not_guaranteed path).
// ------------------------------------------------------------------------------------------------
template <class VInfo,
          template <class, int, int, int, requirement> class V,
          class CInfo,
          template <class, int, int, int, requirement> class C,
          class KeyT,
          int Threads,
          int N,
          int K,
          requirement Req,
          requirement CReq = Req>
int run_cell(int argc, char** argv)
{
  options o              = parse_options(argc, argv);
  constexpr key_type kt  = key_traits<KeyT>::type;
  constexpr bool v_ok    = VInfo::supported(kt, Threads, N, K, Req);
  constexpr bool c_ok    = CInfo::supported(kt, Threads, N, K, CReq);
  constexpr bool same_ab = std::is_same_v<VInfo, CInfo> && (Req == CReq);
  const std::string control_name =
    std::string(CInfo::id) + (CReq != Req ? std::string("@") + to_string(CReq) : std::string());

  json root = json::object();
  root.add("harness_version", harness_version);
  root.add("timestamp", now_iso());
  root.add("date", today());
  root.add("cell", contract_json<VInfo, KeyT, Threads, N, K, Req>());
  root.add("variant_id", VInfo::id);
  root.add("control_id", CInfo::id);
  root.add("control_name", control_name);
  root.add("control_requirement", to_string(CReq));
  root.add("control_is_aa", same_ab);
  root.add("pattern", o.pattern);
  root.add("variant_supported", v_ok);
  root.add("control_supported", c_ok);
  root.add("oracle_selftest", oracle_selftest(N, K));

  if constexpr (!v_ok)
  {
    root.add("status", "variant_unsupported");
    json cells = json::array();
    root.add("cells", cells);
  }
  else
  {
    device_info dev = query_device();
    json d          = json::object();
    d.add("name", dev.name);
    d.add("sms", dev.sms);
    d.add("cc", std::to_string(dev.major) + "." + std::to_string(dev.minor));
    d.add("cuda_runtime", cuda_version_string(dev.runtime));
    d.add("cuda_driver", cuda_version_string(dev.driver));
    d.add("clock_khz", dev.clock_khz);
    root.add("device", d);

    const canary_values can0 = run_canary(dev);

    using VA   = V<KeyT, Threads, N, K, Req>;
    using VCfg = cell_cfg<VInfo, VA, KeyT, Threads, N, K, Req>;
    root.add("variant_static", adapter_static_json<VCfg>());
    adapter_result vr = cell_runner<VCfg>::run(o, dev);

    adapter_result cr;
    bool have_control = false;
    if constexpr (c_ok)
    {
      using CA   = C<KeyT, Threads, N, K, CReq>;
      using CCfg = cell_cfg<CInfo, CA, KeyT, Threads, N, K, CReq>;
      root.add("control_static", adapter_static_json<CCfg>());
      cr           = cell_runner<CCfg>::run(o, dev);
      have_control = true;
    }
    const canary_values can1 = run_canary(dev);

    json can = json::object();
    can.add("start_lat_cycles_per_op", can0.lat_cycles_per_op);
    can.add("end_lat_cycles_per_op", can1.lat_cycles_per_op);
    can.add("start_thr_us", can0.thr_us);
    can.add("end_thr_us", can1.thr_us);
    root.add("canary", can);

    root.add("variant", adapter_json(vr));
    if (have_control)
    {
      root.add("control", adapter_json(cr));
    }
    root.add("status", vr.oracle_ok ? (have_control ? "ok" : "ok_no_control") : "oracle_failed");
    root.add("cells",
             vr.oracle_ok ? make_cells<KeyT>(vr, have_control ? &cr : nullptr, control_name, Threads, N, K, Req,
                                             VA::output, o.pattern, can0, can1)
                          : json::array());

    // Short human summary on stdout (one line per regime), everything else goes to the JSON file
    printf("%s %s T=%d N=%d K=%d %s %s: oracle %s (%d cases)", VInfo::id, to_string(kt), Threads, N, K, to_string(Req),
           o.pattern.c_str(), vr.oracle_ok ? "PASS" : "FAIL", vr.oracle_cases);
    if (vr.has_latency)
    {
      printf(" | lat %.0f cyc (raw %.0f, noop %.0f, r2 %.4f)", vr.lat_value, vr.lat_raw, vr.lat_noop, vr.lat_r2);
      if (have_control && cr.has_latency)
      {
        printf(" ctrl %.0f", cr.lat_value);
      }
    }
    if (vr.has_throughput)
    {
      printf(" | thr %.1f Gelem/s (occ %d, regs %d, ceiling %.0f)", vr.thr_value, vr.thr_res.occupancy,
             vr.thr_res.registers, vr.thr_noop);
      if (have_control && cr.has_throughput)
      {
        printf(" ctrl %.1f", cr.thr_value);
      }
    }
    printf("\n");
    if (!vr.oracle_ok)
    {
      for (auto& f : vr.oracle_failures)
      {
        printf("  FAIL %s\n", f.c_str());
      }
    }
  }

  if (!o.out.empty())
  {
    FILE* f = fopen(o.out.c_str(), "w");
    if (!f)
    {
      fprintf(stderr, "cannot write %s\n", o.out.c_str());
      return 4;
    }
    const std::string s = root.str();
    fwrite(s.data(), 1, s.size(), f);
    fputc('\n', f);
    fclose(f);
  }
  return 0;
}

} // namespace topk
